'use strict';
const PRODUCTS=[['🥛','우유',2000],['🍞','식빵',1500],['🍎','사과',1000],['🥚','계란',3000],['🍌','바나나',1500],['🧃','주스',2500],['🐟','참치',1000],['🍜','라면',2000],['🍪','쿠키',1000],['🍓','딸기',3000],['🧀','치즈',2500],['🥕','당근',500]];
const $=id=>document.getElementById(id), won=n=>'₩'+n.toLocaleString('ko-KR');
let items=[],selected=new Set(),target=5000,score=0,combo=0,maxCombo=0,served=0,deadline=0,lastSuccess=0,active=false,busy=false,timer,round=0,audio,sound=true,best=0;
try{best=Math.max(0,Number(localStorage.getItem('exact-mart-best'))||0);sound=localStorage.getItem('exact-mart-sound')!=='off'}catch{}
function beep(success=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime;[0,...(success?[.09,.18]:[])].forEach((delay,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=success?[660,880,1100][i]:520;gain.gain.setValueAtTime(.065,t+delay);gain.gain.exponentialRampToValueAtTime(.001,t+delay+.12);osc.connect(gain);gain.connect(audio.destination);osc.start(t+delay);osc.stop(t+delay+.13)})}catch{}}
function updateSound(){$('sound').textContent=sound?'♪ 효과음':'♪ 효과음 꺼짐';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'효과음 끄기':'효과음 켜기')}
function randomProduct(){return [...PRODUCTS[Math.floor(Math.random()*PRODUCTS.length)]]}
function chooseTarget(board,rng=Math.random){const ids=Array.from({length:board.length},(_,i)=>i);for(let i=ids.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}return ids.slice(0,2+Math.floor(rng()*3)).reduce((s,i)=>s+board[i][2],0)}
function renderBoard(){const focused=document.activeElement?.dataset?.index;$('board').replaceChildren(...items.map(([emoji,name,price],i)=>{const b=document.createElement('button');b.className='product';b.dataset.index=i;b.disabled=!active||busy;b.setAttribute('aria-label',`${name} ${price}원`);b.setAttribute('aria-pressed',String(selected.has(i)));b.classList.toggle('selected',selected.has(i));b.innerHTML=`<span class="emoji" aria-hidden="true">${emoji}</span><span class="name">${name}</span><span class="price">${won(price)}</span>`;b.onclick=()=>toggle(i);return b}));if(focused!==undefined)$('board').children[Number(focused)]?.focus({preventScroll:true})}
function summary(){const sum=[...selected].reduce((s,i)=>s+items[i][2],0);$('sum').textContent=won(sum);$('count').textContent=selected.size+'개';$('target').textContent=won(target);$('score').textContent=score.toLocaleString();$('best').textContent=best.toLocaleString();$('equation').textContent=selected.size?[...selected].map(i=>items[i][2].toLocaleString()).join(' + '):'상품을 누르면 여기에 담겨요';$('difference').textContent=sum===target?'딱 맞아요! 계산해 주세요':sum>target?`${(sum-target).toLocaleString()}원 초과했어요`:`${(target-sum).toLocaleString()}원 더 담아 주세요`;document.querySelector('.receipt').classList.toggle('exact',sum===target);document.querySelector('.receipt').classList.toggle('over',sum>target);$('checkout').disabled=!active||busy||!selected.size;$('clear').disabled=!active||busy||!selected.size;$('customer').textContent=`${served+1}번째 손님`}
function notice(text,type=''){$('notice').textContent=text;$('notice').className=type}
function toggle(i){if(!active||busy||tick())return;selected.has(i)?selected.delete(i):selected.add(i);beep();const b=$('board').children[i];b.classList.toggle('selected',selected.has(i));b.setAttribute('aria-pressed',String(selected.has(i)));summary()}
function tick(){if(!active)return true;const now=performance.now(),remaining=Math.max(0,deadline-now),seconds=Math.ceil(remaining/1000);$('time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('timebar').style.width=(remaining/90000*100)+'%';document.querySelector('.shop').classList.toggle('urgent',seconds<=15);if(lastSuccess&&now-lastSuccess>5000){combo=0;lastSuccess=0;$('combo').textContent='다시 콤보에 도전!'}else if(combo){$('combo').textContent=`${combo}배 콤보 · ${Math.max(0,(5000-(now-lastSuccess))/1000).toFixed(1)}초`}if(!remaining){finish();return true}return false}
function start(){round++;clearInterval(timer);items=[...PRODUCTS.map(p=>[...p]),[...PRODUCTS[11]],[...PRODUCTS[1]],[...PRODUCTS[2]],[...PRODUCTS[7]]];selected.clear();target=5000;score=combo=maxCombo=served=0;lastSuccess=0;busy=false;active=true;deadline=performance.now()+90000;$('welcome').close();$('result').close();$('combo').textContent='잘 부탁해요!';notice('많이 담을수록 고득점 · 5초 안에 연속 계산하면 콤보!');beep();renderBoard();summary();tick();timer=setInterval(tick,100)}
function finish(){active=false;busy=false;clearInterval(timer);const record=score>best;best=Math.max(best,score);try{localStorage.setItem('exact-mart-best',String(best))}catch{}$('final-score').textContent=score.toLocaleString();$('served').textContent=served+'명';$('maxcombo').textContent=maxCombo+'배';$('final-best').textContent=best.toLocaleString()+'점';$('result-title').textContent=record?'새로운 최고 기록!':'수고했어요, 점장님!';renderBoard();summary();$('result').showModal()}
function checkout(){if(!active||busy||!selected.size||tick())return;const sum=[...selected].reduce((s,i)=>s+items[i][2],0);if(sum!==target){deadline-=3000;combo=0;lastSuccess=0;$('combo').textContent='다시 도전해요!';notice('금액이 달라요! −3초 · 상품을 다시 골라 주세요','error');tick();return}const now=performance.now();combo=lastSuccess&&now-lastSuccess<=5000?Math.min(5,combo+1):1;maxCombo=Math.max(maxCombo,combo);lastSuccess=now;const earned=selected.size*10*combo;score+=earned;served++;busy=true;const version=round,chosen=[...selected];beep(true);notice(`삑! ${chosen.length}개 담기 성공 · +${earned}점`,'success');chosen.forEach(i=>$('board').children[i].classList.add('leaving'));summary();setTimeout(()=>{if(version!==round||!active)return;chosen.forEach(i=>items[i]=randomProduct());selected.clear();target=chooseTarget(items);busy=false;renderBoard();summary()},300)}
$('start').onclick=start;$('restart').onclick=start;$('checkout').onclick=checkout;$('clear').onclick=()=>{if(!active||busy||tick())return;selected.clear();renderBoard();summary()};$('sound').onclick=()=>{sound=!sound;updateSound();try{localStorage.setItem('exact-mart-sound',sound?'on':'off')}catch{}beep()};$('help').onclick=()=>{notice('상품당 10점 × 콤보 배수 · 5초 안에 연속 성공 · 오답은 −3초')};document.addEventListener('keydown',e=>{if(e.key==='Enter'&&active&&e.target.tagName!=='BUTTON'){e.preventDefault();checkout()}if(e.key==='Escape'&&active&&!busy){selected.clear();renderBoard();summary()}});for(const id of ['welcome','result'])$(id).addEventListener('cancel',e=>e.preventDefault());document.addEventListener('visibilitychange',()=>{if(active)tick()});items=[...PRODUCTS,...PRODUCTS.slice(0,4)];updateSound();renderBoard();summary();$('welcome').showModal();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_mart_game',description:'Read the current checkout puzzle, selected items, target, score, and game status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({active,target,score,items:items.map((p,i)=>({index:i,name:p[1],price:p[2],selected:selected.has(i)}))})})).catch(()=>{})}catch{}}
